Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {
    "x": {
      "field": "Revenue",
      "type": "quantitative",
      "axis": {"title": "Revenue", "format": "$,.2s"}
    },
    "y": {
      "field": "Gross Margin %",
      "type": "quantitative",
      "axis": {"title": "Gross Margin %", "format": ".0%"}
    },
    "tooltip": [
      {"field": "Product Name", "type": "nominal", "title": "Product"},
      {"field": "Revenue", "type": "quantitative", "format": "$,.0f"},
      {"field": "Gross Margin %", "type": "quantitative", "format": ".1%"}
    ]
  },
  "layer": [
    {
      "description": "Neutral points",
      "mark": {"type": "circle", "tooltip": true},
      "encoding": {"opacity": {"value": 0.2}}
    },
    {
      "description": "Selected points",
      "mark": {"type": "circle", "tooltip": true},
      "encoding": {
        "opacity": {
          "condition": {"test": {"field": "__selected__", "equal": "on"}, "value": 1},
          "value": 0
        }
      }
    },
    {
      "description": "Cross-highlighted points",
      "mark": {"type": "circle", "tooltip": true},
      "encoding": {
        "opacity": {
          "condition": {"test": "datum[''Gross Margin %__highlightStatus''] === ''on'' && datum[''Gross Margin %__highlight''] !== null", "value": 1},
          "value": 0
        }
      }
    }
  ]
}
'
